'use strict';
const HEADER = (what) => `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// ${what}
// Generated by foundry-invariant-kit. This is a starting point for your own
// invariant testing, not a guarantee of correctness or security. Review every
// property, add protocol-specific ones, and tune the bounds below.
`;
const importLine = (name, rel, global) => (global ? `import "${rel}";` : `import {${name}} from "${rel}";`);

const ASSET = (A) => `${HEADER(`Minimal mintable ERC-20 used as the underlying asset in the ${A.replace(/Asset$/, '')} invariant suite.`)}
contract ${A} {
    string public name = "Mock Asset";
    string public symbol = "MOCK";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) allowance[from][msg.sender] = a - amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
`;
module.exports = { HEADER, importLine, ASSET };
